def test_build_answer_prompt_truncates_long_content():
    long_content = "x" * (m.MAX_CONTEXT_CHARS + 100)
    results = [{"content": long_content, "source": "s.php", "start_line": 1,
                "end_line": 2, "namespace": "N", "class": "C", "method": "M", "type": "file"}]
    prompt = m.build_answer_prompt("Q", results)
    assert "x" * m.MAX_CONTEXT_CHARS in prompt
    assert "x" * (m.MAX_CONTEXT_CHARS + 1) not in prompt
    assert "...[CONTENT TRUNCATED FOR SIZE]..." in prompt


def test_parse_answer_valid_json():
    raw = json.dumps({
        "simple": "Simple answer",
        "technical": "Technical answer",
        "diagram_type": "mermaid",
        "diagram_code": "graph TD\nA-->B"
    })
    result = m.parse_answer(raw)
    assert result["simple"] == "Simple answer"
    assert result["technical"] == "Technical answer"
    assert result["diagram_type"] == "mermaid"
    assert result["diagram_code"] == "graph TD\nA-->B"


def test_parse_answer_invalid_json_fallback():
    result = m.parse_answer("This is not JSON at all")
    assert result["simple"] == "This is not JSON at all"
    assert result["technical"] == ""
    assert result["diagram_type"] is None
    assert result["diagram_code"] is None


def test_parse_answer_json_array_fallback():
    result = m.parse_answer("[1, 2, 3]")
    assert result["simple"] == "[1, 2, 3]"
    assert result["technical"] == ""
    assert result["diagram_type"] is None
    assert result["diagram_code"] is None


