def test_parse_answer_with_markdown_fences():
    raw = "```json\n" + json.dumps({
        "simple": "S",
        "technical": "T",
        "diagram_type": "mermaid",
        "diagram_code": "graph TD"
    }) + "\n```"
    result = m.parse_answer(raw)
    assert result["simple"] == "S"
    assert result["technical"] == "T"
    assert result["diagram_type"] == "mermaid"
    assert result["diagram_code"] == "graph TD"
